+using ContosoUniversity.Controllers;
+using ContosoUniversity.Data;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using ContosoUniversity.Tests.Helpers;
+using Microsoft.AspNetCore.Http;
+using Microsoft.AspNetCore.Mvc;
+using Xunit;
+
+namespace ContosoUniversity.Tests.Controllers
+{
+    public class NotificationsControllerTests : IDisposable
+    {
+        private readonly SchoolContext _context;
+        private readonly NotificationsController _controller;
+        private readonly NotificationService _notificationService;
+
+        public NotificationsControllerTests()
+        {
+            _context = TestDbContextHelper.CreateContext();
+            _controller = new NotificationsController(_context);
+            _controller.ControllerContext = new ControllerContext
+            {
+                HttpContext = new DefaultHttpContext()
+            };
+            _notificationService = new NotificationService();
+            // Drain the queue
+            while (_notificationService.ReceiveNotification() != null) { }
+        }
+
+        public void Dispose()
+        {
+            // Drain the queue to prevent cross-test contamination
+            while (_notificationService.ReceiveNotification() != null) { }
+            _controller.Dispose();
+            _context.Dispose();
+            _notificationService.Dispose();
+        }
+
+        [Fact]
+        public void GetNotifications_EmptyQueue_ReturnsSuccessWithZeroCount()
+        {
+            var result = _controller.GetNotifications();
+
+            Assert.NotNull(result);
+            var value = result.Value;
+            Assert.NotNull(value);
+
+            // Use dynamic to access anonymous type properties
+            var json = System.Text.Json.JsonSerializer.Serialize(value);
+            var doc = System.Text.Json.JsonDocument.Parse(json);
+            Assert.True(doc.RootElement.GetProperty("success").GetBoolean());
+            Assert.Equal(0, doc.RootElement.GetProperty("count").GetInt32());
+        }
+
+        [Fact]
+        public void GetNotifications_WithNotifications_ReturnsUpTo10()
+        {
+            // Enqueue some notifications via the shared static queue
+            for (int i = 0; i < 12; i++)
+            {
+                _notificationService.SendNotification("Test", i.ToString(), $"Item{i}", EntityOperation.CREATE);
+            }
+
+            var result = _controller.GetNotifications();
+
+            var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
+            var doc = System.Text.Json.JsonDocument.Parse(json);
+            Assert.True(doc.RootElement.GetProperty("success").GetBoolean());
+            // Max 10 notifications returned
+            Assert.True(doc.RootElement.GetProperty("count").GetInt32() <= 10);
+        }
+
+        [Fact]
+        public void MarkAsRead_ReturnsSuccessJson()
+        {
+            var result = _controller.MarkAsRead(1);
+
+            var json = System.Text.Json.JsonSerializer.Serialize(result.Value);
+            var doc = System.Text.Json.JsonDocument.Parse(json);
+            Assert.True(doc.RootElement.GetProperty("success").GetBoolean());
+        }
+
+        [Fact]
+        public void Index_ReturnsView()
+        {
+            var result = _controller.Index();
+
+            Assert.IsType<ViewResult>(result);
+        }
+    }
+}
